// <auto-imports> — generated by wire.mjs, do not edit by hand
import { getOwnedActor } from "./actors.js";
import { MODULE_ID } from "./constants.js";
import { recordRevocableChange } from "./offline.js";
// </auto-imports>
// Class advancement (level up / down) — extracted from mobile-bridge.js.

// =============================================================================
// Class advancement (level up / down) — slice 3.1
// =============================================================================
//
// We drive dnd5e's AdvancementManager programmatically. The manager builds a
// list of advancement steps when constructed via `forLevelChange`; for each
// step we call `advancement.apply(level, data)` (public stable API) instead of
// rendering dnd5e's HTML form. The clone actor lives in memory until commit.
//
// State (the `clone` and the step list) is held in `advancementSessions` —
// keyed by sessionId — only on the primary GM client. Players never touch
// this map directly; mobile clients send sessionId back over the socket and
// the GM client looks it up.

export const advancementSessions = new Map();
export const ADVANCEMENT_SESSION_TTL_MS = 15 * 60 * 1000;

/** Drop sessions older than the TTL — called on every begin/submit. */
export function pruneAdvancementSessions() {
  const now = Date.now();
  for (const [id, sess] of advancementSessions.entries()) {
    if (now - sess.createdAt > ADVANCEMENT_SESSION_TTL_MS) {
      advancementSessions.delete(id);
      console.log(`[${MODULE_ID}] Advancement session ${id} expired (TTL)`);
    }
  }
}

/**
 * Is this an advancement step belonging to a character being created?
 *
 * Walking those steps is part of making a character, which any player may do,
 * while levelling an existing one stays behind the Trusted gate. The exemption
 * is tied to the session `actor.class.add` opened - not to the action name, so
 * it cannot be claimed by asking for the level-up flow directly.
 */
export function isCreationAdvancementCall(action, payload) {
  if (!String(action).startsWith("class.advancement.")) return false;
  const session = advancementSessions.get(String(payload?.sessionId ?? ""));
  return session?.creation === true;
}

export function getAdvancementSession(user, sessionId) {
  if (!sessionId) throw new Error("sessionId is required");
  const sess = advancementSessions.get(sessionId);
  if (!sess) throw new Error(`Advancement session not found: ${sessionId}`);
  if (sess.userId !== user.id) {
    throw new Error("Advancement session belongs to a different user");
  }
  return sess;
}

/** Create the dnd5e AdvancementManager class accessor (lazy — system loads after init). */
export function getAdvancementManagerClass() {
  const ctor = dnd5e?.applications?.advancement?.AdvancementManager
    ?? game.dnd5e?.applications?.advancement?.AdvancementManager
    ?? CONFIG?.DND5E?.applications?.advancement?.AdvancementManager;
  if (!ctor) throw new Error("dnd5e AdvancementManager not available — is the dnd5e system active?");
  return ctor;
}

/**
 * Build a transport DTO for a single advancement step. Slice 3.1 implements
 * a real view only for HitPoints; every other non-automatic step type is
 * collapsed into an "autoApply" placeholder so the wizard can still walk
 * through them (the player just clicks Next, server applies whatever the
 * advancement returns from `automaticApplicationValue`, or skips silently
 * with a warning if not possible).
 */
export async function buildStepView(step, sessionId, totalSteps, currentIndex) {
  const flow = step?.flow;
  const advancement = flow?.advancement;
  if (!flow || !advancement) return null;

  const className = step.class?.item?.name ?? flow.item?.name ?? "";
  const level = step.class?.level ?? flow.level ?? 0;
  const advancementType = advancement.constructor?.typeName
    ?? advancement.type
    ?? advancement.constructor?.name
    ?? "Unknown";

  const base = {
    sessionId,
    totalSteps,
    currentIndex,
    advancementType,
    advancementId: advancement.id ?? null,
    title: advancement.title ?? advancementType,
    className,
    level
  };

  if (advancementType === "HitPoints" || advancement.constructor?.name === "HitPointsAdvancement") {
    const hitDieValue = Number(advancement.hitDieValue ?? 0);
    return {
      ...base,
      kind: "hitPoints",
      hitDie: advancement.hitDie ?? `d${hitDieValue || 0}`,
      hitDieValue,
      averageValue: hitDieValue ? Math.floor(hitDieValue / 2) + 1 : 0
    };
  }

  // --- ItemGrant: show the list of items being granted ---
  if (advancementType === "ItemGrant" || advancement.constructor?.name === "ItemGrantAdvancement") {
    const cfgItems = advancement.configuration?.items ?? [];
    const items = [];
    for (const entry of cfgItems) {
      try {
        const doc = await fromUuid(entry.uuid);
        items.push({
          uuid: entry.uuid,
          name: doc?.name ?? entry.uuid.split(".").pop() ?? "???",
          img: doc?.img ?? null,
          optional: !!entry.optional
        });
      } catch {
        items.push({ uuid: entry.uuid, name: entry.uuid.split(".").pop() ?? "???", img: null, optional: !!entry.optional });
      }
    }
    return {
      ...base,
      kind: "itemGrant",
      items
    };
  }

  // --- ScaleValue: show the new value at this level ---
  if (advancementType === "ScaleValue" || advancement.constructor?.name === "ScaleValueAdvancement") {
    let scaleValue = "";
    try {
      const sv = advancement.valueForLevel?.(level);
      scaleValue = sv?.display ?? sv?.formula ?? sv?.value?.toString() ?? "";
    } catch { /* fallback to empty */ }
    return {
      ...base,
      kind: "scaleValue",
      scaleValue
    };
  }

  // --- Trait: show available trait choices (skills, tools, weapon profs, etc.) ---
  if (advancementType === "Trait" || advancement.constructor?.name === "TraitAdvancement") {
    const mode = advancement.configuration?.mode ?? "default";
    const modeLabel = { default: "Владение", expertise: "Экспертиза", upgrade: "Улучшение", mastery: "Мастерство" }[mode] ?? mode;

    let count = advancement.maxTraits ?? 1;
    let options = [];
    let chosenOptions = [];
    try {
      const chosen = new Set(advancement.value?.chosen ?? []);
      const unfulfilled = await advancement.unfulfilledChoices?.();
      const optionLookup = new Map();
      addSelectChoicesToLookup(optionLookup, unfulfilled?.choices);

      if (chosen.size === 0) {
        for (const entry of unfulfilled?.available ?? []) {
          const set = entry.choices?.asSet?.() ?? new Set();
          if (set.size === 1) chosen.add([...set][0]);
        }
      }

      const result = await advancement.availableChoices(chosen);
      if (result) {
        addSelectChoicesToLookup(optionLookup, result.choices);
        options = selectChoicesToTraitOptions(result.choices);
        options.sort((a, b) => a.label.localeCompare(b.label));
      }
      chosenOptions = [...chosen].map((key) => ({
        key,
        label: optionLookup.get(key) ?? traitKeyFallbackLabel(key)
      }));
    } catch (e) {
      console.warn(`[${MODULE_ID}] Trait.availableChoices failed:`, e);
    }
    if (!options.length && !chosenOptions.length) {
      // Not fatal — the phone lets the step through — but it is worth saying
      // which advancement on which item offered the player nothing at all.
      console.warn(
        `[${MODULE_ID}] Trait advancement "${advancement.title ?? advancementType}" on ` +
        `"${flow.item?.name ?? "?"}" offered no choices (mode=${mode}).`
      );
    }

    return {
      ...base,
      kind: "trait",
      traitMode: mode,
      traitModeLabel: modeLabel,
      traitCount: count,
      traitChosen: chosenOptions,
      traitOptions: options
    };
  }

  // --- AbilityScoreImprovement: show ability scores + optional feat choice ---
  if (advancementType === "AbilityScoreImprovement" || advancement.constructor?.name === "AbilityScoreImprovementAdvancement") {
    const cfg = advancement.configuration ?? {};
    const points = cfg.points ?? 2;
    const cap = cfg.cap ?? 2;
    const abilityMax = cfg.max ?? 20;
    const locked = cfg.locked instanceof Set ? [...cfg.locked] : (Array.isArray(cfg.locked) ? cfg.locked : []);
    const fixed = cfg.fixed ?? {};
    // advancement.allowFeat getter may fail if the module-scope `dnd5e` var
    // is unavailable outside the system bundle. Read the setting directly.
    let allowFeat = false;
    try {
      allowFeat = !!advancement.allowFeat;
    } catch {
      // Fallback: read the game setting and check item type manually.
      try {
        const isClass = (advancement.item?.type ?? flow.item?.type) === "class";
        const featsEnabled = game.settings.get("dnd5e", "allowFeats");
        const isModern = game.dnd5e?.settings?.rulesVersion === "modern"
          || CONFIG?.DND5E?.rulesVersion === "modern";
        allowFeat = isClass && (featsEnabled || isModern);
      } catch { /* give up — no feats */ }
    }
    console.log(`[${MODULE_ID}] ASI step: allowFeat=${allowFeat}, points=${points}, cap=${cap}`);

    // Current ability scores from the clone actor on the session manager.
    const clone = flow.advancement?.actor ?? step.class?.item?.actor;
    const abilities = {};
    const abilityOrder = ["str", "dex", "con", "int", "wis", "cha"];
    for (const key of abilityOrder) {
      const ab = clone?.system?.abilities?.[key];
      abilities[key] = {
        score: ab?.value ?? 10,
        max: Math.max(ab?.max ?? 20, abilityMax),
        locked: locked.includes(key),
        fixed: fixed[key] ?? 0
      };
    }

    // Pre-load feat list if feats are allowed.
    const feats = [];
    if (allowFeat) {
      for (const pack of game.packs) {
        if (pack.metadata?.type !== "Item") continue;
        try {
          const index = await pack.getIndex({ fields: ["system.type.value", "type", "img"] });
          for (const entry of index) {
            if (entry.type !== "feat") continue;
            if (entry.system?.type?.value !== "feat") continue;
            feats.push({
              uuid: entry.uuid ?? `Compendium.${pack.collection}.${entry._id}`,
              name: entry.name ?? "???",
              img: entry.img ?? null
            });
          }
        } catch (e) {
          console.warn(`[${MODULE_ID}] Failed to index pack ${pack.collection} for feats:`, e);
        }
      }
      // World items.
      for (const item of game.items ?? []) {
        if (item.type !== "feat" || item.system?.type?.value !== "feat") continue;
        feats.push({ uuid: item.uuid, name: item.name, img: item.img ?? null });
      }
      feats.sort((a, b) => a.name.localeCompare(b.name));
    }

    return {
      ...base,
      kind: "asi",
      points,
      cap,
      abilities,
      allowFeat,
      feats
    };
  }

  // --- Subclass: load available subclass items from compendium packs ---
  if (advancementType === "Subclass" || advancement.constructor?.name === "SubclassAdvancement") {
    const classItem = flow.item ?? step.class?.item;
    const classIdentifier = classItem?.system?.identifier ?? classItem?.identifier ?? "";
    const subclasses = [];
    if (classIdentifier) {
      for (const pack of game.packs) {
        if (pack.metadata?.type !== "Item") continue;
        try {
          const index = await pack.getIndex({ fields: ["system.classIdentifier", "type", "img"] });
          for (const entry of index) {
            if (entry.type !== "subclass") continue;
            if (entry.system?.classIdentifier !== classIdentifier) continue;
            subclasses.push({
              uuid: entry.uuid ?? `Compendium.${pack.collection}.${entry._id}`,
              name: entry.name ?? "???",
              img: entry.img ?? null
            });
          }
        } catch (e) {
          console.warn(`[${MODULE_ID}] Failed to index pack ${pack.collection} for subclasses:`, e);
        }
      }
    }
    // Also check world items.
    for (const item of game.items ?? []) {
      if (item.type !== "subclass") continue;
      if (item.system?.classIdentifier !== classIdentifier) continue;
      subclasses.push({ uuid: item.uuid, name: item.name, img: item.img ?? null });
    }
    return {
      ...base,
      kind: "subclass",
      classIdentifier,
      subclasses
    };
  }

  if (advancementType === "Size") {
    const sizes = [...(advancement.configuration?.sizes ?? [])];
    return {
      ...base,
      kind: "size",
      sizes: sizes.map((key) => ({
        key,
        label: game.i18n.localize(CONFIG.DND5E?.actorSizes?.[key]?.label ?? key)
      }))
    };
  }

  // Fallback — let the wizard show "this step will be auto-applied" and the
  // server will try `automaticApplicationValue()` on submit.
  return {
    ...base,
    kind: "autoApply",
    description: `Advancement type "${advancementType}" не поддерживается мобильным мастером — будет применено автоматически (если возможно). Тонкую настройку выполните в Foundry.`
  };
}

export function addSelectChoicesToLookup(lookup, choices) {
  for (const opt of selectChoicesToTraitOptions(choices)) lookup.set(opt.key, opt.label);
}

export function selectChoicesToTraitOptions(choices) {
  const options = [];
  choices?.forEach?.((key, choice) => {
    if (choice?.children || choice?.selectable === false) return;
    options.push({ key, label: choice.label ?? traitKeyFallbackLabel(key) });
  });
  return options;
}

export function traitKeyFallbackLabel(key) {
  const parts = String(key ?? "").split(":");
  const id = parts.at(-1) ?? key;
  const type = parts[0];
  if (type === "skills") {
    return game.i18n.localize(CONFIG.DND5E.skills?.[id]?.label ?? id);
  }
  return id;
}

/**
 * Walk forward over consecutive automatic steps, mirroring AdvancementManager#forward
 * but without rendering. Each automatic step is applied via the public
 * `apply/reverse/restore` methods on the Advancement document. Stops at the
 * first non-automatic step or when the list is exhausted.
 */
export async function advanceAutomaticSteps(session) {
  while (session.stepIndex < session.manager.steps.length) {
    const step = session.manager.steps[session.stepIndex];
    if (!step?.automatic) break;
    await applyOneStep(session, step, /*automaticData*/ undefined);
    session.stepIndex++;
  }
}

/**
 * Apply a single advancement step on the session's clone actor. Mirrors the
 * branches of AdvancementManager#forward but without DOM submission.
 *
 * For "forward" steps with explicit `data`, calls `advancement.apply(level, data)`.
 * For "forward" steps without data, tries `automaticApplicationValue(level)`
 *   and falls back to skipping with a warning.
 * For "reverse" steps, captures retained data via `advancement.reverse(level)`
 *   so the user can later restore (we keep it on the step for now).
 * For "restore" steps, calls `advancement.restore(level, retainedData)`.
 * For "delete" steps (only generated for level→0 reductions), removes the
 *   item from the clone.
 */
export async function applyOneStep(session, step, data) {
  const flow = step.flow;
  const type = step.type;
  const preEmbeddedItems = Array.from(session.manager.clone.items);

  if (type === "delete" && step.item) {
    session.manager.clone.items.delete(step.item.id);
  } else if (type === "reverse" && flow) {
    await flow.retainData(await flow.advancement.reverse(flow.level));
    step.retainedData = flow.retainedData;
  } else if (type === "restore" && flow) {
    await flow.advancement.restore(flow.level, flow.retainedData);
  } else if (type === "forward" && flow) {
    let payload = data;
    // The mobile client sends `{}` for autoApply steps. Treat null/undefined/
    // empty object the same way: ask the advancement what its automatic value
    // would be and use that. If the advancement has none — log a warning and
    // skip the step (the wizard still advances and the player can fix it
    // later in Foundry).
    const isEmpty = payload == null
      || (typeof payload === "object" && Object.keys(payload).length === 0);

    if (isEmpty) {
      const auto = flow.advancement.automaticApplicationValue?.(flow.level);
      if (auto === false || auto == null) {
        console.warn(
          `[${MODULE_ID}] Advancement step ${flow.advancement.constructor?.name}@${flow.level} has no auto value and no data — skipping. Configure manually in Foundry if needed.`
        );
        // Skip without applying anything; the class-level pin below still runs.
      } else {
        await flow.advancement.apply(flow.level, auto);
      }
    } else {
      await flow.advancement.apply(flow.level, payload);
    }
  }

  // Mirror AdvancementManager#forward — pin the class item level to the step's class level.
  if (step.class?.item) {
    let level = step.class.level;
    if (step.type === "reverse") level -= 1;
    step.class.item.updateSource({ "system.levels": level });
  }

  synthesizeChangedItemSteps(session, preEmbeddedItems);

  // reset() re-prepares the clone after synthetic steps have been injected,
  // matching dnd5e's AdvancementManager#forward ordering.
  session.manager.clone.reset();
}

/**
 * Mirrors dnd5e AdvancementManager#synthesizeSteps for added and removed items.
 * This is what makes level-down undo advancements from items granted by a
 * previous step, such as a feat selected through ASI.
 */
export function synthesizeChangedItemSteps(session, preEmbeddedItems) {
  const manager = session.manager;
  const initialIds = manager.steps.reduce((ids, step) => {
    if (step.synthetic || !step.flow?.item) return ids;
    ids.add(step.flow.item.id);
    return ids;
  }, new Set());
  const preIds = new Set(preEmbeddedItems.map((item) => item.id));
  const postIds = new Set(manager.clone.items.map((item) => item.id));
  const addedIds = [...postIds].filter((id) => !preIds.has(id) && !initialIds.has(id));
  const deletedIds = [...preIds].filter((id) => !postIds.has(id));

  for (const addedId of addedIds) {
    const item = manager.clone.items.get(addedId);
    if (!item?.hasAdvancement) continue;

    let handledLevel = 0;
    for (let idx = session.stepIndex; idx < manager.steps.length; idx++) {
      const getLevel = (step) =>
        (item.system.advancementClassLinked ? undefined : step?.level)
          ?? step?.flow?.level
          ?? step?.class?.level;
      const thisLevel = getLevel(manager.steps[idx]);
      const nextLevel = getLevel(manager.steps[idx + 1]);
      if ((thisLevel < handledLevel) || (thisLevel === nextLevel)) continue;

      const flows = [];
      for (let level = handledLevel; level <= thisLevel; level++) {
        flows.push(...manager.constructor.flowsForLevel(item, level, { findExisting: manager.steps }));
      }
      const steps = flows.map((flow) => ({ type: "forward", flow, synthetic: true }));
      if (steps.length) {
        manager.steps.splice(idx + 1, 0, ...steps);
        console.log(
          `[${MODULE_ID}] Injected ${steps.length} synthetic advancement step(s) from granted item "${item.name}" ` +
          `through level ${thisLevel}`
        );
      }
      idx += steps.length;
      handledLevel = nextLevel ?? handledLevel;
    }
  }

  const currentStep = manager.steps[session.stepIndex];
  if ((currentStep?.type === "delete") && currentStep.synthetic) return;
  for (const deletedId of deletedIds) {
    let item = preEmbeddedItems.find((i) => i.id === deletedId);
    if (!item?.hasAdvancement) continue;

    manager.clone.updateSource({ items: [item.toObject()] });
    item = manager.clone.items.get(item.id);

    const steps = [];
    for (let level = manager.clone.system.details.level ?? 0; level >= 0; level--) {
      for (const flow of manager.constructor.flowsForLevel(item, level).reverse()) {
        steps.push({ type: "reverse", flow, automatic: true, synthetic: true });
      }
    }
    steps.push({ type: "delete", flow: currentStep?.flow, item, automatic: true, synthetic: true });
    manager.steps.splice(session.stepIndex + 1, 0, ...steps);
    console.log(
      `[${MODULE_ID}] Injected ${steps.length} synthetic advancement step(s) for removed item "${item.name}"`
    );
  }
}

export async function classAdvancementBegin(user, actorId, classId, delta) {
  pruneAdvancementSessions();
  const actor = getOwnedActor(user, actorId);
  if (!classId) throw new Error("classId is required");
  const numericDelta = Number(delta);
  if (!Number.isFinite(numericDelta) || numericDelta === 0) {
    throw new Error("delta must be a non-zero integer");
  }
  const classItem = actor.items.get(classId);
  if (!classItem || classItem.type !== "class") {
    throw new Error(`Class item not found on actor: ${classId}`);
  }

  // Auto-cancel any stale session for the same actor+class (e.g. app crashed/restarted).
  for (const [key, existing] of advancementSessions.entries()) {
    if (existing.userId === user.id && existing.actorId === actorId && existing.classId === classId) {
      console.warn(`[${MODULE_ID}] Replacing stale advancement session ${key} for ${actorId}/${classId}`);
      advancementSessions.delete(key);
    }
  }

  const Manager = getAdvancementManagerClass();
  const manager = Manager.forLevelChange(actor, classId, numericDelta);
  if (!manager.steps.length) {
    throw new Error("AdvancementManager не построил ни одного шага — возможно, нечего применять.");
  }

  return beginAdvancementSession(user, actor, manager, `class=${classItem.name} delta=${numericDelta}`, {
    classId,
    delta: numericDelta,
    priorLevel: Math.max(0, Math.floor(Number(classItem.system?.levels) || 0)),
    className: classItem.name
  });
}

/**
 * Opens a wizard session over an already-built AdvancementManager and returns
 * the first step the player actually has to answer.
 *
 * The manager is the only thing that differs between levelling an existing
 * class and putting the first one on a new character, so everything after it is
 * shared - including `submit`, `commit` and `cancel`, which only ever touch
 * `session.manager`.
 */
export async function beginAdvancementSession(user, actor, manager, label, extra = {}) {
  const sessionId = foundry.utils.randomID();
  const session = {
    sessionId,
    userId: user.id,
    actorId: actor.id,
    manager,
    stepIndex: 0,
    createdAt: Date.now(),
    ...extra
  };
  advancementSessions.set(sessionId, session);
  console.log(
    `[${MODULE_ID}] Advancement begin: session=${sessionId} actor=${actor.name} ${label} steps=${manager.steps.length}`
  );

  // Auto-skip leading automatic steps so the player lands on the first real choice.
  await advanceAutomaticSteps(session);

  return advancementSessionView(session);
}

/** Visible (non-automatic) step index for the wizard progress display. */
export function visibleStepIndex(session) {
  let n = 0;
  for (let i = 0; i <= session.stepIndex && i < session.manager.steps.length; i++) {
    if (!session.manager.steps[i].automatic) n++;
  }
  return Math.max(0, n - 1);
}

/**
 * Steps the wizard back, undoing what the step being left had applied.
 *
 * Mirrors `AdvancementManager#backward`: each advancement is reversed rather
 * than merely forgotten, because applying one twice is not the same as applying
 * it once — an item grant would arrive again. Automatic steps are stepped over
 * on the way back, exactly as they are on the way forward.
 */
export async function classAdvancementBack(user, sessionId) {
  const session = getAdvancementSession(user, sessionId);
  pruneAdvancementSessions();
  if (!advancementCanGoBack(session)) {
    throw new Error("This is the first step");
  }

  const manager = session.manager;
  do {
    session.stepIndex--;
    const step = manager.steps[session.stepIndex];
    if (!step) break;
    const flow = step.flow;
    const preItems = Array.from(manager.clone.items);

    if (step.type === "delete" && step.item) {
      manager.clone.updateSource({ items: [step.item] });
    } else if (step.type === "reverse" && flow) {
      await flow.advancement.restore(flow.level, flow.retainedData);
    } else if (flow) {
      await flow.retainData(await flow.advancement.reverse(flow.level));
    }

    clearSyntheticAdvancementSteps(manager, session.stepIndex, preItems);
    manager.clone.reset();
  } while (manager.steps[session.stepIndex]?.automatic);

  return advancementSessionView(session);
}

/**
 * Is there anything to go back to?
 *
 * Only a step the player actually answered counts: the automatic ones before it
 * were stepped over without ever being shown, and stopping on one would look
 * like the button did nothing.
 */
export function advancementCanGoBack(session) {
  for (let idx = session.stepIndex - 1; idx >= 0; idx--) {
    if (!session.manager.steps[idx]?.automatic) return true;
  }
  return false;
}

/**
 * Drops steps that only existed because of what the step being reversed had
 * added. Reproduces `AdvancementManager#clearSyntheticSteps`, which is private.
 */
export function clearSyntheticAdvancementSteps(manager, stepIndex, preItems) {
  const preIds = new Set(preItems.map((item) => item.id));
  const postIds = new Set(manager.clone.items.map((item) => item.id));
  const modified = new Set();
  for (const id of preIds) if (!postIds.has(id)) modified.add(id);
  for (const id of postIds) if (!preIds.has(id)) modified.add(id);
  for (let idx = manager.steps.length - 1; idx > stepIndex; idx--) {
    const step = manager.steps[idx];
    if (step?.synthetic && modified.has(step.flow?.item?.id)) manager.steps.splice(idx, 1);
  }
}

/** The wizard's current position, as the phone draws it. */
export async function advancementSessionView(session) {
  const manager = session.manager;
  const totalSteps = manager.steps.filter((step) => !step.automatic).length;
  const sessionId = session.sessionId;
  if (session.stepIndex >= manager.steps.length) {
    return { sessionId, totalSteps, currentIndex: 0, currentStep: null, done: true, canGoBack: false };
  }
  return {
    sessionId,
    totalSteps,
    currentIndex: visibleStepIndex(session),
    currentStep: await buildStepView(
      manager.steps[session.stepIndex], sessionId, totalSteps, visibleStepIndex(session)
    ),
    done: false,
    canGoBack: advancementCanGoBack(session)
  };
}

export async function classAdvancementSubmit(user, sessionId, data) {
  const session = getAdvancementSession(user, sessionId);
  pruneAdvancementSessions();

  if (session.stepIndex >= session.manager.steps.length) return advancementSessionView(session);

  const currentStep = session.manager.steps[session.stepIndex];
  await applyOneStep(session, currentStep, data);
  session.stepIndex++;

  // Walk through any automatic steps that follow.
  await advanceAutomaticSteps(session);

  return advancementSessionView(session);
}

/**
 * Mirrors AdvancementManager#complete: copies the modified clone back onto
 * the real actor with `{ isAdvancement: true }` so dnd5e treats the change as
 * a level-up rather than an arbitrary edit. Drops the session afterwards.
 */
export async function classAdvancementCommit(user, sessionId) {
  const session = getAdvancementSession(user, sessionId);
  const manager = session.manager;
  const result = await commitAdvancementManager(manager);
  // A genuine level-up (not the class step of character creation, which is
  // logged elsewhere) is revocable: rolling the class back to its prior level
  // unwinds the granted features through the same advancement machinery.
  if (session.classId && !session.creation && session.priorLevel != null) {
    try {
      const actor = getOwnedActor(user, session.actorId);
      const classItem = actor.items.get(session.classId);
      const newLevel = Math.max(0, Math.floor(Number(classItem?.system?.levels) || 0));
      if (newLevel !== session.priorLevel) {
        await recordRevocableChange(
          actor, user,
          `${session.className ?? classItem?.name ?? "Class"}: level ${session.priorLevel} → ${newLevel}`,
          { operation: "class.level", classId: session.classId, priorLevel: session.priorLevel, newLevel }
        );
      }
    } catch (err) {
      console.warn(`[${MODULE_ID}] could not log revocable level-up`, err);
    }
  }
  advancementSessions.delete(sessionId);
  return result;
}

export async function commitAdvancementManager(manager) {
  const actor = manager.actor;
  const updates = manager.clone.toObject();
  const items = updates.items;
  delete updates.items;

  const initial = { toCreate: [], toUpdate: [], toDelete: actor.items.map((i) => i.id) };
  const { toCreate, toUpdate, toDelete } = items.reduce((obj, item) => {
    if (!actor.items.get(item._id)) {
      obj.toCreate.push(item);
    } else {
      obj.toUpdate.push(item);
      const idx = obj.toDelete.indexOf(item._id);
      if (idx >= 0) obj.toDelete.splice(idx, 1);
    }
    return obj;
  }, initial);

  if (Hooks.call("dnd5e.preAdvancementManagerComplete", manager, updates, toCreate, toUpdate, toDelete) === false) {
    throw new Error("Изменения отменены хуком dnd5e.preAdvancementManagerComplete");
  }

  await Promise.all([
    actor.update(updates, { isAdvancement: true }),
    actor.createEmbeddedDocuments("Item", toCreate, { keepId: true, isAdvancement: true }),
    actor.updateEmbeddedDocuments("Item", toUpdate, { isAdvancement: true }),
    actor.deleteEmbeddedDocuments("Item", toDelete, { isAdvancement: true })
  ]);

  Hooks.callAll("dnd5e.advancementManagerComplete", manager);

  const newLevel = actor.system?.details?.level ?? null;
  console.log(`[${MODULE_ID}] Advancement commit: actor=${actor.name} → level=${newLevel}`);
  return { committed: true, newLevel };
}

export function classAdvancementCancel(user, sessionId) {
  if (!sessionId) return { cancelled: false };
  const sess = advancementSessions.get(sessionId);
  if (!sess) return { cancelled: false };
  if (sess.userId !== user.id) {
    throw new Error("Advancement session belongs to a different user");
  }
  advancementSessions.delete(sessionId);
  console.log(`[${MODULE_ID}] Advancement cancelled: session=${sessionId}`);
  return { cancelled: true };
}

